//! Asymmetric key types beyond RSA/P-256..P-521/Ed25519/X25519: secp256k1 (ECDSA, ECDH,
//! JWK, SEC1), Ed448 (RFC 8032 signatures, byte-identical to OpenSSL), X448, and DSA
//! (generation with modulusLength/divisorLength, DER and IEEE-P1363 signatures), with
//! PKCS#8/SPKI/JWK import and export and Node's errors; also WebCrypto Ed448/X448. Keys were
//! generated by Node 22 and the expected output is Node's.

use std::process::Command;

const NODE_BIN: &str = env!("CARGO_BIN_EXE_pi-jsrt-node");

fn run(script: &str, with_stderr: bool) -> String {
    let dir = tempfile::tempdir().unwrap();
    let path = dir.path().join("t.js");
    std::fs::write(&path, script).unwrap();
    let out = Command::new(NODE_BIN).arg(&path).output().unwrap();
    let mut s = String::from_utf8_lossy(&out.stdout).into_owned();
    if with_stderr {
        s.push_str(&String::from_utf8_lossy(&out.stderr));
    }
    s
}

#[test]
fn key_types_match_node() {
    assert_eq!(run(KEYS, true), KEYS_EXPECTED);
}

#[test]
fn webcrypto_ed448_x448_match_node() {
    assert_eq!(run(WEB448, false), WEB448_EXPECTED);
}

